float rataRata(const float data[], unsigned int jumlah) {
  if (jumlah == 0) return 0; // Pemanggil tetap harus memastikan ada data.
  float total = 0;
  for (unsigned int i = 0; i < jumlah; i++) total += data[i];
  return total / jumlah;
}
