const int TOMBOL = 2;
int bacaanTerakhir = HIGH, stabil = HIGH;
unsigned long berubahPada = 0, hitungan = 0;
void setup() { Serial.begin(115200); pinMode(TOMBOL, INPUT_PULLUP); }
void loop() {
  int bacaan = digitalRead(TOMBOL);
  unsigned long sekarang = millis();
  if (bacaan != bacaanTerakhir) berubahPada = sekarang;
  if (sekarang - berubahPada >= 30UL && bacaan != stabil) {
    stabil = bacaan;
    if (stabil == LOW) Serial.println(++hitungan);
  }
  bacaanTerakhir = bacaan;
}

enum Keadaan { SIAP, AKTIF };
