    keadaan = AKTIF; masukPada = sekarang; Serial.println("AKTIF");
  } else if (keadaan == AKTIF && sekarang - masukPada >= 2000UL) {
    keadaan = SIAP; masukPada = sekarang; Serial.println("SIAP");
  }
}

