# Tambahkan ke bridge yang sudah menginisialisasi Firebase Admin.
import math
import re
import time
from firebase_admin import db

def save_event(event):
    event_id = event.get("messageId")
    if not isinstance(event_id, str) or not re.fullmatch(r"[0-9a-f]{32}", event_id):
        raise ValueError("messageId tidak valid")
    if event.get("deviceId") != "esp32-01" or event.get("unit") != "C":
        raise ValueError("Identitas/unit salah")
    temperature = event.get("temperature")
    if type(temperature) not in (int, float) or not math.isfinite(temperature) or not -40 <= temperature <= 125:
        raise ValueError("Suhu tidak valid")
    measured = event.get("measuredAt")
    if type(measured) is not int or not 0 < measured <= int(time.time() * 1000) + 5000:
        raise ValueError("Waktu tidak valid")
    if type(event.get("simulated")) is not bool:
        raise ValueError("Penanda simulasi tidak valid")
    value = {"messageId": event_id, "deviceId": "esp32-01", "temperature": temperature,
             "unit": "C", "simulated": event["simulated"], "measuredAt": measured}
    root = db.reference("devices/esp32-01")
    def first_write(current):
        if current is not None:
            if any(current.get(key) != field for key, field in value.items()):
                raise ValueError("ID sama tetapi isi kejadian berbeda")
            return current
        return {**value, "receivedAt": {".sv": "timestamp"}}
    saved = root.child("history").child(event_id).transaction(first_write)
    def newest(current):
        if current is None or current.get("measuredAt", 0) < saved["measuredAt"]:
            return saved
        return current
    root.child("latest").transaction(newest)
# ACK aplikasi hanya dikirim setelah save_event selesai tanpa error.
# Jika proses berhenti antara dua transaksi, retry dengan ID sama memperbaiki latest.

// Tambahkan impor ini pada dashboard yang Firebase-nya sudah diinisialisasi.
import { ref, query, orderByChild, limitToLast, onValue } from "firebase/database";
// database berasal dari getDatabase(app) pada materi dashboard.
function watchHistory(database, render) {
  const selected = query(ref(database, "devices/esp32-01/history"),
    orderByChild("measuredAt"), limitToLast(50));
  return onValue(selected, snapshot => {
    const samples = [];
    snapshot.forEach(child => { samples.push(child.val()); });
    render(samples);
  }, error => { console.error("Riwayat gagal dibaca:", error.code); });
}

