def validate_command(command, now_ms):
    if command.get("deviceId") != "esp32-01":
        raise ValueError("Target salah")
    if command.get("action") not in ("SET_ON", "SET_OFF"):
        raise ValueError("Action tidak dikenal")
    request_id = command.get("requestId")
    if not isinstance(request_id, str) or not 1 <= len(request_id) <= 64:
        raise ValueError("ID tidak valid")
    issued, expires = command.get("issuedAt"), command.get("expiresAt")
    if type(issued) is not int or type(expires) is not int:
        raise ValueError("Waktu harus integer milidetik")
    if not issued <= now_ms < expires or expires - issued > 30000:
        raise ValueError("Belum berlaku, kedaluwarsa, atau durasi berlebihan")
    return command["action"]

