#include <WiFi.h>
#include <PubSubClient.h>
#include <DHT.h>
#include <math.h>

// ESP32 klasik: DHT22 DATA GPIO4; output driver aktif-HIGH GPIO23.
// Hanya pakai driver DC yang terdokumentasi menerima logika 3,3 V.
const int SENSOR_PIN = 4, DRIVER_PIN = 23;
DHT sensor(SENSOR_PIN, DHT22);
WiFiClient network; // LAN lab; untuk broker internet gunakan client TLS.
PubSubClient mqtt(network);
bool kipas = false;
unsigned long bacaPada = 0, cobaPada = 0, wifiPada = 0;

void setup() {
  pinMode(DRIVER_PIN, OUTPUT); digitalWrite(DRIVER_PIN, LOW);
  Serial.begin(115200); sensor.begin();
  WiFi.mode(WIFI_STA);
  WiFi.begin("GANTI_SSID_2_4_GHZ", "GANTI_PASSWORD_WIFI");
  mqtt.setServer("192.168.1.10", 1883);
  mqtt.setSocketTimeout(2); mqtt.setBufferSize(384);
}
void loop() {
  unsigned long now = millis();
  if (WiFi.status() != WL_CONNECTED && now - wifiPada >= 10000UL) {
    wifiPada = now; WiFi.reconnect();
  }
  if (WiFi.status() == WL_CONNECTED && !mqtt.connected() && now - cobaPada >= 10000UL) {
    cobaPada = now;
    mqtt.connect("esp32-01", "esp32", "GANTI_PASSWORD_ESP32");
  }
  if (mqtt.connected()) mqtt.loop();
  if (now - bacaPada < 5000UL) return;
  bacaPada = now;
  float suhu = sensor.readTemperature();
  if (!isfinite(suhu) || suhu < -40 || suhu > 80) {
    kipas = false; digitalWrite(DRIVER_PIN, LOW);
    Serial.println("SENSOR_GAGAL; output OFF; telemetry valid tidak dikirim");
    return;
  }
  if (suhu >= 30.0f) kipas = true;
  else if (suhu <= 28.0f) kipas = false;
  digitalWrite(DRIVER_PIN, kipas ? HIGH : LOW);
  char payload[180];
  snprintf(payload, sizeof(payload),
    "{\"deviceId\":\"esp32-01\",\"temperature\":%.1f,\"unit\":\"C\",\"simulated\":false}", suhu);
  Serial.print(payload); Serial.println(kipas ? " kipas=ON" : " kipas=OFF");
  if (mqtt.connected()) mqtt.publish("lab/esp32-01/telemetry", payload, false);
  // Kendali lokal tetap dilakukan walau publish gagal. Belum ada outbox/history.
}
